content:
.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.header {
  background: white;
  border-bottom: 1px solid #e5e7eb;
  padding: 1rem 1.5rem;
  position: sticky;
  top: 0;
  z-index: 10;
}

.header-content h1 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: #111827;
}

.stats-strip {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.stat-label {
  font-size: 0.75rem;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 500;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 600;
  color: #111827;
}

.stat-success {
  color: #059669;
}

.stat-warning {
  color: #d97706;
}

.stat-danger {
  color: #dc2626;
}

.main {
  flex: 1;
  padding: 1.5rem;
  max-width: 1600px;
  width: 100%;
  margin: 0 auto;
}

.controls {
  display: flex;
  gap: 1rem;
  margin-bottom: 1.5rem;
  flex-wrap: wrap;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 0.5rem 0.75rem;
  flex: 1;
  min-width: 250px;
}

.search-box svg {
  color: #9ca3af;
  flex-shrink: 0;
}

.search-box input {
  border: none;
  outline: none;
  flex: 1;
  font-size: 0.875rem;
  color: #111827;
}

.search-box input::placeholder {
  color: #9ca3af;
}

.filters {
  display: flex;
  gap: 0.5rem;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 6px;
  padding: 0.25rem;
}

.filter-btn {
  padding: 0.375rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: #6b7280;
  border-radius: 4px;
  transition: all 0.15s;
  text-transform: capitalize;
  white-space: nowrap;
}

.filter-btn:hover {
  background: #f3f4f6;
  color: #111827;
}

.filter-btn.active {
  background: #2563eb;
  color: white;
}

.table-container {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  overflow: hidden;
  display: block;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}

.table thead {
  background: #f9fafb;
  border-bottom: 1px solid #e5e7eb;
}

.table th {
  text-align: left;
  padding: 0.75rem 1rem;
  font-weight: 600;
  color: #374151;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.table th.sortable {
  cursor: pointer;
  user-select: none;
  transition: background 0.15s;
}

.table th.sortable:hover {
  background: #f3f4f6;
}

.table th.sortable svg {
  display: inline-block;
  vertical-align: middle;
  margin-left: 0.25rem;
  transition: transform 0.2s;
}

.table th.sortable svg.flip {
  transform: rotate(180deg);
}

.table td {
  padding: 0.875rem 1rem;
  border-bottom: 1px solid #f3f4f6;
  color: #111827;
}

.table tbody tr {
  transition: background 0.15s;
}

.table tbody tr.clickable-row {
  cursor: pointer;
}

.table tbody tr:hover {
  background: #f9fafb;
}

.checkbox-col {
  width: 40px;
  padding-left: 1rem !important;
}

.checkbox-col input[type="checkbox"] {
  width: 16px;
  height: 16px;
  cursor: pointer;
  accent-color: #2563eb;
}

.actions-col {
  width: 40px;
  text-align: right;
  padding-right: 1rem !important;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 4px;
  color: #6b7280;
  transition: all 0.15s;
}

.icon-btn:hover {
  background: #f3f4f6;
  color: #111827;
}

.key-name {
  font-weight: 500;
}

.name-cell {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.warning-icon {
  color: #d97706;
  flex-shrink: 0;
}

.scopes {
  display: flex;
  gap: 0.375rem;
  flex-wrap: wrap;
}

.scope-badge {
  display: inline-block;
  padding: 0.125rem 0.5rem;
  background: #eff6ff;
  color: #1e40af;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
  white-space: nowrap;
}

.scope-badge.more {
  background: #f3f4f6;
  color: #6b7280;
}

.scope-badge.large {
  padding: 0.25rem 0.625rem;
  font-size: 0.8125rem;
}

.date-cell {
  color: #6b7280;
  white-space: nowrap;
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border-radius: 12px;
  font-size: 0.75rem;
  font-weight: 500;
  white-space: nowrap;
}

.status-healthy {
  background: #d1fae5;
  color: #065f46;
}

.status-stale {
  background: #fef3c7;
  color: #92400e;
}

.status-expiring {
  background: #fed7aa;
  color: #9a3412;
}

.status-leaked {
  background: #fee2e2;
  color: #991b1b;
}

.status-revoked {
  background: #f3f4f6;
  color: #4b5563;
}

.popover-backdrop {
  position: fixed;
  inset: 0;
  z-index: 19;
}

.popover {
  position: absolute;
  right: 0;
  top: 100%;
  margin-top: 0.5rem;
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  z-index: 20;
  min-width: 180px;
  padding: 0.5rem;
}

.popover button {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
  color: #374151;
  border-radius: 4px;
  transition: background 0.15s;
  text-align: left;
}

.popover button:hover {
  background: #f3f4f6;
}

.popover button.danger {
  color: #dc2626;
}

.popover button.danger:hover {
  background: #fee2e2;
}

.bulk-actions {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: #1f2937;
  border-top: 1px solid #374151;
  padding: 1rem 1.5rem;
  z-index: 15;
  box-shadow: 0 -4px 6px -1px rgba(0, 0, 0, 0.1);
}

.bulk-actions-content {
  max-width: 1600px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.bulk-count {
  color: white;
  font-weight: 500;
  font-size: 0.875rem;
}

.bulk-buttons {
  display: flex;
  gap: 0.75rem;
}

.bulk-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: #374151;
  color: white;
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  transition: background 0.15s;
}

.bulk-btn:hover {
  background: #4b5563;
}

.bulk-btn.danger {
  background: #dc2626;
}

.bulk-btn.danger:hover {
  background: #b91c1c;
}

.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 30;
  animation: fadeIn 0.2s;
}

.drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  max-width: 600px;
  background: white;
  z-index: 31;
  display: flex;
  flex-direction: column;
  box-shadow: -4px 0 6px -1px rgba(0, 0, 0, 0.1);
  animation: slideIn 0.3s ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideIn {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.drawer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 1.5rem;
  border-bottom: 1px solid #e5e7eb;
}

.drawer-header h2 {
  font-size: 1.25rem;
  font-weight: 600;
  color: #111827;
  margin-bottom: 0.25rem;
}

.drawer-subtitle {
  font-size: 0.875rem;
  color: #6b7280;
}

.drawer-content {
  flex: 1;
  overflow-y: auto;
  padding: 1.5rem;
}

.drawer-section {
  margin-bottom: 2rem;
}

.drawer-section:last-child {
  margin-bottom: 0;
}

.drawer-section h3 {
  font-size: 0.875rem;
  font-weight: 600;
  color: #111827;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.detail-item {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.detail-label {
  font-size: 0.75rem;
  color: #6b7280;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 500;
}

.key-id {
  font-family: 'Monaco', 'Courier New', monospace;
  font-size: 0.75rem;
  background: #f3f4f6;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  color: #374151;
  word-break: break-all;
}

.warning-banner {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.75rem;
  background: #fef3c7;
  border: 1px solid #fbbf24;
  border-radius: 6px;
  color: #92400e;
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.scopes-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.audit-trail {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.audit-event {
  display: flex;
  gap: 0.75rem;
}

.audit-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: #f3f4f6;
  border-radius: 50%;
  color: #6b7280;
  flex-shrink: 0;
}

.audit-details {
  flex: 1;
}

.audit-action {
  font-weight: 500;
  color: #111827;
  font-size: 0.875rem;
  margin-bottom: 0.25rem;
}

.audit-meta {
  font-size: 0.75rem;
  color: #6b7280;
}

.audit-extra {
  font-size: 0.8125rem;
  color: #6b7280;
  margin-top: 0.375rem;
  padding: 0.5rem;
  background: #f9fafb;
  border-radius: 4px;
}

.empty-state {
  padding: 4rem 2rem;
  text-align: center;
  color: #6b7280;
}

.mobile-list {
  display: none;
}

@media (max-width: 1024px) {
  .table-container {
    display: none;
  }

  .mobile-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .mobile-card {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 1rem;
    cursor: pointer;
    transition: box-shadow 0.15s;
  }

  .mobile-card:hover {
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  }

  .mobile-card-header {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 0.75rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #f3f4f6;
  }

  .mobile-card-header input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
    accent-color: #2563eb;
    flex-shrink: 0;
  }

  .mobile-card-title {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: 600;
    color: #111827;
  }

  .mobile-card-body {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
  }

  .mobile-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    font-size: 0.875rem;
  }

  .mobile-row .label {
    color: #6b7280;
    font-weight: 500;
    white-space: nowrap;
  }

  .drawer {
    max-width: 100%;
  }
}

@media (max-width: 768px) {
  .header {
    padding: 1rem;
  }

  .header-content h1 {
    font-size: 1.25rem;
  }

  .stats-strip {
    gap: 1rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }

  .main {
    padding: 1rem;
  }

  .controls {
    flex-direction: column;
  }

  .search-box {
    min-width: 100%;
  }

  .filters {
    width: 100%;
    overflow-x: auto;
    flex-wrap: nowrap;
  }

  .bulk-actions {
    padding: 1rem;
  }

  .bulk-actions-content {
    flex-direction: column;
    align-items: stretch;
  }

  .bulk-buttons {
    justify-content: stretch;
  }

  .bulk-btn {
    flex: 1;
    justify-content: center;
  }

  .drawer-content {
    padding: 1rem;
  }

  .detail-grid {
    grid-template-columns: 1fr;
  }
}

import React, { useState, useMemo } from 'react';
import { Search, ChevronDown, MoreVertical, RotateCw, XCircle, Edit3, FileText, X, AlertTriangle, CheckCircle2, Clock, Shield } from 'lucide-react';
import { generateMockKeys } from './mockData';
import './App.css';

const FILTERS = ['all', 'active', 'stale', 'expiring', 'over-scoped'];

function App() {
  const [keys, setKeys] = useState(generateMockKeys(25));
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState('all');
  const [sortConfig, setSortConfig] = useState({ key: 'lastUsed', direction: 'desc' });
  const [selectedKeys, setSelectedKeys] = useState(new Set());
  const [openPopover, setOpenPopover] = useState(null);
  const [drawerKey, setDrawerKey] = useState(null);

  const filteredAndSortedKeys = useMemo(() => {
    let filtered = keys.filter(key => {
      const matchesSearch = 
        key.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        key.owner.toLowerCase().includes(searchQuery.toLowerCase()) ||
        key.scopes.some(s => s.toLowerCase().includes(searchQuery.toLowerCase()));

      if (!matchesSearch) return false;

      switch (activeFilter) {
        case 'active':
          return key.status === 'healthy';
        case 'stale':
          return key.status === 'stale';
        case 'expiring':
          return key.status === 'expiring';
        case 'over-scoped':
          return key.overScoped;
        default:
          return true;
      }
    });

    filtered.sort((a, b) => {
      let aVal = a[sortConfig.key];
      let bVal = b[sortConfig.key];

      if (sortConfig.key === 'lastUsed' || sortConfig.key === 'created' || sortConfig.key === 'expires') {
        aVal = new Date(aVal).getTime();
        bVal = new Date(bVal).getTime();
      }

      if (sortConfig.key === 'scopes') {
        aVal = a.scopes.length;
        bVal = b.scopes.length;
      }

      if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
      return 0;
    });

    return filtered;
  }, [keys, searchQuery, activeFilter, sortConfig]);

  const stats = useMemo(() => {
    const total = keys.length;
    const active = keys.filter(k => k.status === 'healthy').length;
    const overScoped = keys.filter(k => k.overScoped).length;
    const expiringThisWeek = keys.filter(k => {
      const daysUntilExpiry = Math.floor((new Date(k.expires) - new Date()) / (1000 * 60 * 60 * 24));
      return daysUntilExpiry <= 7 && daysUntilExpiry >= 0;
    }).length;

    return { total, active, overScoped, expiringThisWeek };
  }, [keys]);

  const handleSort = (key) => {
    setSortConfig(prev => ({
      key,
      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedKeys(new Set(filteredAndSortedKeys.map(k => k.id)));
    } else {
      setSelectedKeys(new Set());
    }
  };

  const handleSelectKey = (id) => {
    const newSelected = new Set(selectedKeys);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedKeys(newSelected);
  };

  const handleAction = (action, keyId) => {
    setOpenPopover(null);

    if (action === 'view') {
      const key = keys.find(k => k.id === keyId);
      setDrawerKey(key);
      return;
    }

    setKeys(prev => prev.map(k => {
      if (k.id === keyId) {
        switch (action) {
          case 'rotate':
            return { ...k, status: 'healthy', lastUsed: new Date().toISOString(), created: new Date().toISOString() };
          case 'revoke':
            return { ...k, status: 'revoked' };
          case 'edit':
            return { ...k, overScoped: false };
          default:
            return k;
        }
      }
      return k;
    }));
  };

  const handleBulkAction = (action) => {
    setKeys(prev => prev.map(k => {
      if (selectedKeys.has(k.id)) {
        switch (action) {
          case 'revoke':
            return { ...k, status: 'revoked' };
          case 'rotate':
            return { ...k, status: 'healthy', lastUsed: new Date().toISOString(), created: new Date().toISOString() };
          default:
            return k;
        }
      }
      return k;
    }));
    setSelectedKeys(new Set());
  };

  return (
    <div className="app">
      <header className="header">
        <div className="header-content">
          <h1>API Key Management</h1>
          <div className="stats-strip">
            <div className="stat">
              <span className="stat-label">Total Keys</span>
              <span className="stat-value">{stats.total}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Active</span>
              <span className="stat-value stat-success">{stats.active}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Over-scoped</span>
              <span className="stat-value stat-warning">{stats.overScoped}</span>
            </div>
            <div className="stat">
              <span className="stat-label">Expiring This Week</span>
              <span className="stat-value stat-danger">{stats.expiringThisWeek}</span>
            </div>
          </div>
        </div>
      </header>

      <main className="main">
        <div className="controls">
          <div className="search-box">
            <Search size={18} />
            <input
              type="text"
              placeholder="Search keys, owners, scopes..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <div className="filters">
            {FILTERS.map(filter => (
              <button
                key={filter}
                className={`filter-btn ${activeFilter === filter ? 'active' : ''}`}
                onClick={() => setActiveFilter(filter)}
              >
                {filter.replace('-', ' ')}
              </button>
            ))}
          </div>
        </div>

        <div className="table-container">
          <table className="table">
            <thead>
              <tr>
                <th className="checkbox-col">
                  <input
                    type="checkbox"
                    checked={selectedKeys.size === filteredAndSortedKeys.length && filteredAndSortedKeys.length > 0}
                    onChange={handleSelectAll}
                    aria-label="Select all keys"
                  />
                </th>
                <th onClick={() => handleSort('name')} className="sortable">
                  Name {sortConfig.key === 'name' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th onClick={() => handleSort('owner')} className="sortable">
                  Owner {sortConfig.key === 'owner' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th onClick={() => handleSort('scopes')} className="sortable">
                  Scopes {sortConfig.key === 'scopes' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th onClick={() => handleSort('lastUsed')} className="sortable">
                  Last Used {sortConfig.key === 'lastUsed' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th onClick={() => handleSort('created')} className="sortable">
                  Created {sortConfig.key === 'created' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th onClick={() => handleSort('expires')} className="sortable">
                  Expires {sortConfig.key === 'expires' && <ChevronDown size={14} className={sortConfig.direction === 'asc' ? 'flip' : ''} />}
                </th>
                <th>Status</th>
                <th className="actions-col"></th>
              </tr>
            </thead>
            <tbody>
              {filteredAndSortedKeys.map(key => (
                <tr key={key.id} onClick={() => setDrawerKey(key)} className="clickable-row">
                  <td className="checkbox-col" onClick={(e) => e.stopPropagation()}>
                    <input
                      type="checkbox"
                      checked={selectedKeys.has(key.id)}
                      onChange={() => handleSelectKey(key.id)}
                      aria-label={`Select ${key.name}`}
                    />
                  </td>
                  <td className="key-name">
                    <div className="name-cell">
                      <span className="name">{key.name}</span>
                      {key.overScoped && <AlertTriangle size={14} className="warning-icon" />}
                    </div>
                  </td>
                  <td>{key.owner}</td>
                  <td>
                    <div className="scopes">
                      {key.scopes.slice(0, 2).map((scope, i) => (
                        <span key={i} className="scope-badge">{scope}</span>
                      ))}
